def _validate_credentials_and_listener(self):
    if (
        len(self.service_token) < 32
        or self.service_token != self.service_token.strip()
        or any(character.isspace() for character in self.service_token)
    ):
        raise ValueError("EDUGRADE_GRADING_AGENT_TOKEN must contain at least 32 non-whitespace characters")
    if not isinstance(self.host, str) or not self.host:
        raise ValueError("EDUGRADE_GRADING_AGENT_HOST must be a non-empty string")
    if bool(self.tls_cert_file) != bool(self.tls_key_file):
        raise ValueError("grading-agent TLS certificate and key must be configured together")
    # 直接注入 Settings 时也只接受实际布尔值，不能用字符串或整数的真值开启明文监听。
    if type(self.allow_insecure_loopback_http) is not bool:
        raise ValueError("EDUGRADE_GRADING_AGENT_ALLOW_INSECURE_LOOPBACK_HTTP must be a boolean")
    if self.tls_cert_file:
        return
    try:
        address = ipaddress.ip_address(self.host)
    except ValueError:
        address = None
    # 明文仅用于显式开发环境、明确 opt-in 和 IPv4 字面回环地址；不解析 DNS，也不开放 IPv6。
    if (
        self.environment in {"local", "development", "dev", "test"}
        and self.allow_insecure_loopback_http is True
        and isinstance(address, ipaddress.IPv4Address)
        and address.is_loopback
    ):
        return
    raise ValueError(
        "grading-agent TLS certificate and key are required unless explicit development "
        "loopback HTTP is enabled"
    )

def _validate_listener_policy(environment: str, host: str, allow_http: bool, has_certificate: bool) -> None:
    # 不接受字符串或整数的真值；只有明确的布尔授权才能进入开发明文例外。
    if type(allow_http) is not bool:
        raise ValueError("math verifier insecure HTTP opt-in must be a boolean")
    # IPv4Address 也接受整数；只接收字符串，避免直接调用绕过字面地址限制。
    if not isinstance(host, str):
        raise ValueError("EDUGRADE_MATH_VERIFY_HOST must be a string")
    if not host:
        raise ValueError("EDUGRADE_MATH_VERIFY_HOST must not be empty")
    if has_certificate:
        return
    if environment not in {"local", "development", "dev", "test"}:
        raise ValueError("math verifier TLS certificate and key are required in production-like environments")
    if allow_http is not True:
        raise ValueError("math verifier cleartext HTTP requires explicit insecure loopback opt-in")
    # AF_INET 监听器只允许字面 IPv4 回环例外，避免 DNS 解析或通配地址扩展明文暴露范围。
    try:
        address = ipaddress.IPv4Address(host)
    except ipaddress.AddressValueError as exc:
        raise ValueError("math verifier cleartext HTTP requires a literal IPv4 loopback host") from exc
    if not address.is_loopback:
        raise ValueError("math verifier cleartext HTTP requires a literal IPv4 loopback host")
